import React from "react";

const Layout = ({ children }) => {
  return (
    <div className="min-h-screen w-full">
      {/* Background image as fixed full-screen */}
      <div
        className="fixed top-0 left-0 w-full h-full bg-cover bg-center bg-no-repeat -z-10"
        style={{
          backgroundImage: "url('/bg.png')",
        }}
      ></div>

      {/* Dark overlay and global styles */}
      <div className="min-h-screen w-full bg-black bg-opacity-60 text-blue-200 text-xl font-sans">
        {children}
      </div>
    </div>
  );
};

export default Layout;
